begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
insert into branches(id,code,name) values('ec100000-0000-0000-0000-000000000001','QMS-A','Calidad prueba A'),('ec100000-0000-0000-0000-000000000002','QMS-B','Calidad prueba B');
insert into auth.users(id,email) values('ec200000-0000-0000-0000-000000000001','qms-a@example.invalid'),('ec200000-0000-0000-0000-000000000002','qms-b@example.invalid'),('ec200000-0000-0000-0000-000000000003','qms-c@example.invalid');
insert into profiles(id,full_name,branch_id,active) values('ec200000-0000-0000-0000-000000000001','Calidad ejecutor','ec100000-0000-0000-0000-000000000001',true),('ec200000-0000-0000-0000-000000000002','Calidad revisor','ec100000-0000-0000-0000-000000000001',true),('ec200000-0000-0000-0000-000000000003','Lector Calidad','ec100000-0000-0000-0000-000000000001',true);
insert into roles(code,name) values('QMS_TEST_READ','QMS lector de pruebas'),('QMS_TEST_OPERATOR','QMS operador acotado de pruebas');
insert into role_permissions select r.id,p.permission_code from roles r cross join app_permissions p where r.code='QMS_TEST_OPERATOR' and p.permission_code in ('QUALITY_VIEW','QUALITY_WRITE','MANAGEMENT_REVIEW_VIEW','MANAGEMENT_REVIEW_WRITE','WORK_AGENDA_VIEW','WORK_AGENDA_WRITE','WORK_AGENDA_MANAGE','DOCUMENTS_VIEW','DOCUMENTS_WRITE');
insert into work_area_roles select id,'CALIDAD',true,true from roles where code='QMS_TEST_OPERATOR';
insert into role_permissions select id,'QUALITY_VIEW' from roles where code='QMS_TEST_READ';
insert into user_roles(user_id,role_id,branch_id) select v.id,r.id,'ec100000-0000-0000-0000-000000000001'::uuid from (values('ec200000-0000-0000-0000-000000000001'::uuid,'QMS_TEST_OPERATOR'),('ec200000-0000-0000-0000-000000000002'::uuid,'QMS_TEST_OPERATOR'),('ec200000-0000-0000-0000-000000000003'::uuid,'QMS_TEST_READ'))v(id,code) join roles r on r.code=v.code;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
insert into nonconformities(id,code,branch_id,description) values('ec300000-0000-0000-0000-000000000002','QMS-FOREIGN','ec100000-0000-0000-0000-000000000002','Foreign synthetic finding');
set local role authenticated;
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000001',true);
select pg_temp.ok((select count(*)=0 from nonconformities where code='QMS-FOREIGN'),'scoped quality writer cannot read an unauthorized branch');
select pg_temp.denied($q$insert into nonconformities(code,branch_id,description) values('QMS-BAD','ec100000-0000-0000-0000-000000000002','Wrong branch')$q$,'quality cannot insert another branch');
insert into nonconformities(id,code,branch_id,description,owner_user_id,due_date) values('ec300000-0000-0000-0000-000000000001','QMS-NC','ec100000-0000-0000-0000-000000000001','Synthetic trace','ec200000-0000-0000-0000-000000000001',current_date+1);
insert into capa(id,code,nonconformity_id,problem,root_cause,action_plan,owner_user_id,due_date) values('ec400000-0000-0000-0000-000000000001','QMS-CAPA','ec300000-0000-0000-0000-000000000001','Synthetic problem','Synthetic cause','Synthetic plan','ec200000-0000-0000-0000-000000000001',current_date+1);
select pg_temp.ok((select original_due_known and original_due_date=due_date from capa where code='QMS-CAPA'),'new CAPA captures verifiable original deadline');
select pg_temp.denied($q$update capa set original_due_date=current_date+10 where code='QMS-CAPA'$q$,'original CAPA deadline is immutable');
select pg_temp.denied($q$insert into capa(code,nonconformity_id,problem,action_plan) values('QMS-BAD-CAPA','ec300000-0000-0000-0000-000000000002','Wrong scope','Plan')$q$,'CAPA cannot link foreign branch finding');
select pg_temp.denied($q$select qms_capa_action('SAVE_EVIDENCE','{"id":"ec400000-0000-0000-0000-000000000001","revision":1,"evidence_url":"","root_cause":"cause"}')$q$,'CAPA evidence cannot be blank');
select qms_capa_action('SAVE_EVIDENCE','{"id":"ec400000-0000-0000-0000-000000000001","revision":1,"evidence_url":"QMS-EVIDENCE","root_cause":"Cause investigated"}');
select pg_temp.denied($q$select qms_capa_action('SAVE_EVIDENCE','{"id":"ec400000-0000-0000-0000-000000000001","revision":1,"evidence_url":"lost update","root_cause":"cause"}')$q$,'stale CAPA revisions rejected');
select pg_temp.denied($q$select qms_capa_action('VERIFY','{"id":"ec400000-0000-0000-0000-000000000001","revision":2,"effectiveness_status":"EFECTIVA","effectiveness_notes":"Own review"}')$q$,'CAPA executor cannot verify own evidence');
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000002',true);
select qms_capa_action('VERIFY','{"id":"ec400000-0000-0000-0000-000000000001","revision":2,"effectiveness_status":"EFECTIVA","effectiveness_notes":"Independent verification against approved criterion"}');
select pg_temp.ok((select verified_by=auth.uid() and effectiveness_verified_at is not null from capa where code='QMS-CAPA'),'independent CAPA verification stores actor and timestamp');
select pg_temp.denied($q$update capa set status='CERRADA' where code='QMS-CAPA'$q$,'CAPA closure cannot bypass approval');
select pg_temp.denied($q$select qms_record_action('CLOSE_NC','{"id":"ec300000-0000-0000-0000-000000000001","revision":1,"root_cause":"Cause","closure_evidence":"REF"}')$q$,'NC cannot close with outstanding CAPA');
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000001',true);
select qms_capa_action('SAVE_EVIDENCE','{"id":"ec400000-0000-0000-0000-000000000001","revision":3,"evidence_url":"QMS-EVIDENCE-2","root_cause":"Cause investigated"}');
select pg_temp.ok((select effectiveness_status='PENDIENTE' and verified_by is null and effectiveness_verified_at is null and approval_request_id is null from capa where code='QMS-CAPA'),'changed evidence invalidates verification and prior approval');
insert into risk_register(id,risk_code,branch_id,process_name,risk_description,probability,impact) values('ec500000-0000-0000-0000-000000000001','QMS-RISK','ec100000-0000-0000-0000-000000000001','Synthetic process','Synthetic risk',3,4);
select pg_temp.denied($q$select qms_record_action('RISK_UPDATE','{"id":"ec500000-0000-0000-0000-000000000001","revision":1,"status":"ACEPTADO","review_date":"2026-10-31"}')$q$,'risk acceptance requires residual evaluation and evidence');
select qms_record_action('RISK_UPDATE','{"id":"ec500000-0000-0000-0000-000000000001","revision":1,"status":"EN_TRATAMIENTO","existing_controls":"Control","treatment_action":"Treatment","residual_probability":"2","residual_impact":"2","review_date":"2026-10-31","evidence_url":"RISK-REF"}');
select pg_temp.ok((select residual_probability*residual_impact=4 and revision=2 from risk_register where risk_code='QMS-RISK'),'risk assessment stores residual score and revision');
select pg_temp.denied($q$select qms_record_action('RISK_UPDATE','{"id":"ec500000-0000-0000-0000-000000000001","revision":1}')$q$,'stale risk assessments rejected');
reset role;
insert into document_register(id,document_code,title,area,document_type) values('ec600000-0000-0000-0000-000000000001','QMS-DOC','Synthetic procedure','CALIDAD','PROCEDIMIENTO');
set local role authenticated;
insert into document_changes(id,document_id,requested_by,change_reason) values('ec700000-0000-0000-0000-000000000001','ec600000-0000-0000-0000-000000000001',auth.uid(),'Synthetic revision');
select qms_record_action('CHANGE_IMPACT','{"id":"ec700000-0000-0000-0000-000000000001","revision":1,"impact_assessment":"Retrain operators, revise checklist and validate equipment setup"}');
select pg_temp.ok((select revision=2 and impact_assessment like 'Retrain%' from document_changes where id='ec700000-0000-0000-0000-000000000001'),'document change impact links affected work before approval');
select pg_temp.denied($q$select qms_record_action('CHANGE_IMPACT','{"id":"ec700000-0000-0000-0000-000000000001","revision":1,"impact_assessment":"Overwrite"}')$q$,'stale document impact assessment rejected');
select qms_management_action('CREATE_REVIEW',jsonb_build_object('review_code','QMS-REVIEW','review_date',current_date,'period_start',current_date-30,'period_end',current_date,'branch_id','ec100000-0000-0000-0000-000000000001','summary','Synthetic input','decisions','Approve resources for root cause investigation','actions',jsonb_build_array(jsonb_build_object('action_code','QMS-COMMIT','description','Investigate','owner_user_id','ec200000-0000-0000-0000-000000000001','due_date',current_date+1))));
select pg_temp.ok((select count(*)=1 from management_review_actions where action_code='QMS-COMMIT'),'review and real-owner commitment save atomically');
select pg_temp.denied($q$select qms_management_action('CREATE_REVIEW',jsonb_build_object('review_code','QMS-ROLLBACK','review_date',current_date,'period_start',current_date-30,'period_end',current_date,'branch_id','ec100000-0000-0000-0000-000000000001','summary','Input','decisions','Decision','actions',jsonb_build_array(jsonb_build_object('action_code','QMS-ROLLBACK-COMMIT','description','Invalid actor','owner_user_id','ec200000-0000-0000-0000-000000000003','due_date',current_date+1))))$q$,'noneligible commitment owner rolls back whole review');
select pg_temp.ok((select count(*)=0 from management_reviews where review_code='QMS-ROLLBACK'),'failed creation leaves no orphan review');
select pg_temp.denied($q$select qms_management_action('APPROVE_REVIEW',(select jsonb_build_object('id',id,'revision',revision) from management_reviews where review_code='QMS-REVIEW'))$q$,'review author cannot self approve');
select pg_temp.denied($q$select qms_management_action('SAVE_COMMITMENT',(select jsonb_build_object('id',id,'revision',revision,'due_date',current_date+4,'status','ABIERTA') from management_review_actions where action_code='QMS-COMMIT'))$q$,'commitment replanning requires reason');
select qms_management_action('SAVE_COMMITMENT',(select jsonb_build_object('id',id,'revision',revision,'due_date',current_date+4,'status','EN_CURSO','replan_reason','New agreed delivery') from management_review_actions where action_code='QMS-COMMIT'));
select pg_temp.ok((select original_due_date=current_date+1 and due_date=current_date+4 from management_review_actions where action_code='QMS-COMMIT'),'replanning preserves original commitment deadline');
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000002',true);
select qms_management_action('APPROVE_REVIEW',(select jsonb_build_object('id',id,'revision',revision) from management_reviews where review_code='QMS-REVIEW'));
select pg_temp.denied($q$select qms_management_action('CLOSE_REVIEW',(select jsonb_build_object('id',id,'revision',revision) from management_reviews where review_code='QMS-REVIEW'))$q$,'review cannot close with pending commitments');
select pg_temp.denied($q$select qms_management_action('SAVE_COMMITMENT',(select jsonb_build_object('id',id,'revision',revision,'due_date',due_date,'status','CERRADA') from management_review_actions where action_code='QMS-COMMIT'))$q$,'commitment closure requires evidence');
select qms_management_action('SAVE_COMMITMENT',(select jsonb_build_object('id',id,'revision',revision,'due_date',due_date,'status','CERRADA','evidence_reference','QMS-RESULT') from management_review_actions where action_code='QMS-COMMIT'));
select qms_management_action('CLOSE_REVIEW',(select jsonb_build_object('id',id,'revision',revision) from management_reviews where review_code='QMS-REVIEW'));
select pg_temp.ok((select status='CERRADA' from management_reviews where review_code='QMS-REVIEW'),'review closes after approved decisions and evidenced commitments');
select pg_temp.denied($q$update management_reviews set decisions='Rewrite history' where review_code='QMS-REVIEW'$q$,'closed management decisions immutable');
select pg_temp.denied($q$delete from qms_change_history$q$,'quality audit cannot be deleted');
select pg_temp.denied($q$update qms_change_history set actor_id=auth.uid()$q$,'quality audit cannot be rewritten');
select pg_temp.ok((select count(*)>=7 from qms_change_history where source_table='capa' or source_table='management_reviews'),'quality changes preserve audit snapshots');
-- Exercise the existing CAPA approval path after independent verification.
reset role;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
insert into user_roles(user_id,role_id,branch_id) select 'ec200000-0000-0000-0000-000000000002',id,'ec100000-0000-0000-0000-000000000001' from roles where code='CALIDAD';
set local role authenticated;
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000002',true);
select qms_capa_action('VERIFY','{"id":"ec400000-0000-0000-0000-000000000001","revision":4,"effectiveness_status":"EFECTIVA","effectiveness_notes":"Verified revised evidence"}');
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000001',true);
select request_capa_close('ec400000-0000-0000-0000-000000000001','Close after documented independent verification');
select pg_temp.denied($q$select execute_approved_action((select approval_request_id from capa where code='QMS-CAPA'))$q$,'CAPA pending approval cannot execute');
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000002',true);
select decide_approval_request((select approval_request_id from capa where code='QMS-CAPA'),'APROBAR','Independent decision','Evidence reviewed');
select execute_approved_action((select approval_request_id from capa where code='QMS-CAPA'));
select pg_temp.ok((select status='CERRADA' and closed_at is not null from capa where code='QMS-CAPA'),'existing CAPA approval and execution flow remains functional');
select qms_record_action('CLOSE_NC','{"id":"ec300000-0000-0000-0000-000000000001","revision":1,"root_cause":"Cause verified","closure_evidence":"REF-CLOSE"}');
select pg_temp.ok((select status='CERRADA' and closed_by=auth.uid() from nonconformities where code='QMS-NC'),'NC closes with independent conclusion after CAPA closure');
select set_config('request.jwt.claim.sub','ec200000-0000-0000-0000-000000000003',true);
select pg_temp.ok((select count(*)=1 from nonconformities where code='QMS-NC'),'read-only quality role can consult authorized branch');
select pg_temp.denied($q$insert into nonconformities(code,description) values('QMS-READ-WRITE','Read only')$q$,'read-only quality role cannot create findings');
select pg_temp.denied($q$select qms_management_action('CREATE_REVIEW','{}')$q$,'reader cannot invoke management writer');
reset role;
update profiles set active=false where id='ec200000-0000-0000-0000-000000000003';
set local role authenticated;
select pg_temp.ok((select count(*)=0 from nonconformities),'inactive user cannot read quality findings');
select pg_temp.ok((select count(*)=0 from capa),'inactive user cannot read CAPA');
reset role;
select pg_temp.ok(not has_function_privilege('anon','public.qms_capa_action(text,jsonb)','EXECUTE') and not has_function_privilege('anon','public.qms_management_action(text,jsonb)','EXECUTE'),'anonymous cannot invoke quality writers');
select pg_temp.ok((select bool_and(reloptions @> array['security_invoker=true']) from pg_class where oid in ('vw_quality_today'::regclass,'vw_management_review_inputs'::regclass,'vw_capa_control_status'::regclass)),'quality summary views enforce invoker security');
rollback;
